下面这段代码实现了选择排序算法。
void sort(int a[], int n) {
for (int i= 1； i< n; i++){
int x = a[i];
int j= i - 1；
while (j >= 0 && a[j] > x){
a[j+1]= a[j];
j--;
}
a[j+1]= x;
}
}

